WITH latest AS (SELECT * FROM sessions QUALIFY ROW_NUMBER() OVER (PARTITION BY browser, customer_id ORDER BY started_at DESC, id) = 1) SELECT DATE_TRUNC('YEAR', started_at) AS year_start, SORT_ARRAY(COLLECT_SET(country)) AS country_list, MIN(started_at) AS first_seen, SORT_ARRAY(COLLECT_SET(device)) AS device_list, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS span_minutes, SORT_ARRAY(COLLECT_SET(country)) AS country_list_2 FROM latest GROUP BY DATE_TRUNC('YEAR', started_at) HAVING span_minutes >= 0 ORDER BY year_start DESC
